260     * This set_object() thing is to use sanitize at runtime lookup
   261     * application time.  This is very distinct from the regular
   262     * sanitizer operation, so, eventually, separate into another
   263     * type and make hb_aat_apply_context_t use that one instead
   264     * of abusing this one.
   265     */
   266    template <typename T>
   267    inline void set_object (const T& obj)
   268    {
   269      this->start = (const char *) &obj;
   270      this->end = (const char *) &obj + obj.get_size ();
   271      assert (this->start <= this->end); /* Must not overflow. */
   272    }
   273
   274    inline void start_processing (void)
   275    {
   276      this->start = this->blob->data;
   277      this->end = this->start + this->blob->length;
   278      assert (this->start <= this->end); /* Must not overflow. */
   279      this->max_ops = MAX ((unsigned int) (this->end - this->start) * HB_SANITIZE_MAX_OPS_FACTOR,
   280                           (unsigned) HB_SANITIZE_MAX_OPS_MIN);
   281      this->edit_count = 0;
   282      this->debug_depth = 0;
   283
   284      DEBUG_MSG_LEVEL (SANITIZE, start, 0, +1,
   285                       "start [%p..%p] (%lu bytes)",
   286                       this->start, this->end,
   287                       (unsigned long) (this->end - this->start));
   288    }
   289
   290    inline void end_processing (void)
   291    {
   292      DEBUG_MSG_LEVEL (SANITIZE, this->start, 0, -1,
   293                       "end [%p..%p] %u edit requests",
   294                       this->start, this->end, this->edit_count);
   295
   296      hb_blob_destroy (this->blob);
   297      this->blob = nullptr;
   298      this->start = this->end = nullptr;
   299    }
   300
   301    inline bool check_range (const void *base, unsigned int len) const
   302    {
   303      const char *p = (const char *) base;
   304      bool ok = this->start <= p &&
   305                p <= this->end &&
   306                (unsigned int) (this->end - p) >= len &&
   307                this->max_ops-- > 0;
   308
   309      DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   310         "check_range [%p..%p] (%d bytes) in [%p..%p] -> %s",
   311         p, p + len, len,
   312         this->start, this->end,
   313         ok ? "OK" : "OUT-OF-RANGE");
   314
   315      return likely (ok);
   316    }
   317
   318    template <typename T>
   319    inline bool check_array (const T *base, unsigned int len, unsigned int record_size = T::static_size) const
   320    {
   321      const char *p = (const char *) base;
   322      bool overflows = hb_unsigned_mul_overflows (len, record_size);
   323      unsigned int array_size = record_size * len;
   324      bool ok = !overflows && this->check_range (base, array_size);
   325
   326      DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   327         "check_array [%p..%p] (%d*%d=%d bytes) in [%p..%p] -> %s",
   328         p, p + (record_size * len), record_size, len, (unsigned int) array_size,
   329         this->start, this->end,
   330         overflows ? "OVERFLOWS" : ok ? "OK" : "OUT-OF-RANGE");
   331
   332      return likely (ok);
   333    }
